with with_gaps as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval 1 hour then 1 else 0 end as is_new_burst from device_readings) select id, device_code, reading_ts, temp_c, status_bits, sum(is_new_burst) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_no from with_gaps
